describe('Form Fields Accessibility - Associated Labels', () => {
  beforeEach(() => {
    cy.visit('/forms');
    cy.injectAxe();
  });

  it('should have associated labels for all form fields', () => {
    // Test that all input fields have associated labels
    cy.get('input[type="text"], input[type="email"], input[type="password"], textarea, select').each(($input) => {
      const inputId = $input.attr('id');

      // Check if input has an id
      cy.wrap($input).should('have.attr', 'id');

      // Check if there's a corresponding label with matching for attribute
      if (inputId) {
        cy.get(`label[for="${inputId}"]`).should('exist');
        cy.get(`label[for="${inputId}"]`).should('not.be.empty');
      }
    });

    // Run accessibility checks
    cy.checkA11y();
  });

  it('should properly associate labels with form fields using aria-labelledby', () => {
    // Test alternative labeling method using aria-labelledby
    cy.get('input[aria-labelledby]').each(($input) => {
      const labelId = $input.attr('aria-labelledby');

      if (labelId) {
        cy.get(`#${labelId}`).should('exist');
        cy.get(`#${labelId}`).should('have.text').and('not.be.empty');
      }
    });

    cy.checkA11y();
  });

  it('should announce form field labels to screen readers', () => {
    // Test that labels are visible and accessible
    cy.get('label').each(($label) => {
      cy.wrap($label).should('be.visible');
      cy.wrap($label).should('have.css', 'display').and('not.equal', 'none');
      cy.wrap($label).invoke('text').should('not.be.empty');
    });

    // Verify no orphaned labels exist
    cy.get('label').each(($label) => {
      const forAttribute = $label.attr('for');
      if (forAttribute) {
        cy.get(`#${forAttribute}`).should('exist');
      }
    });

    cy.checkA11y();
  });

  it('should handle edge case of hidden labels with aria-label fallback', () => {
    // Test inputs with hidden labels but aria-label present
    cy.get('input[aria-label]').each(($input) => {
      cy.wrap($input).should('have.attr', 'aria-label');
      cy.wrap($input).invoke('attr', 'aria-label').should('not.be.empty');
    });

    // Verify inputs without visible labels have aria-label or aria-labelledby
    cy.get('input:not([aria-label]):not([aria-labelledby])').each(($input) => {
      const inputId = $input.attr('id');
      if (inputId) {
        cy.get(`label[for="${inputId}"]`).should('exist');
      }
    });

    cy.checkA11y();
  });

  it('should ensure form field labels have sufficient contrast', () => {
    // Test label text contrast ratio
    cy.get('label').each(($label) => {
      cy.wrap($label).should('be.visible');

      // Verify label is not hidden or has zero opacity
      cy.wrap($label).should('have.css', 'opacity').and('not.equal', '0');
      cy.wrap($label).should('have.css', 'visibility').and('not.equal', 'hidden');
    });

    cy.checkA11y();
  });

  it('should handle edge case of grouped form fields with fieldset and legend', () => {
    // Test fieldset and legend for grouped inputs
    cy.get('fieldset').each(($fieldset) => {
      cy.wrap($fieldset).within(() => {
        cy.get('legend').should('exist');
        cy.get('legend').should('be.visible');
        cy.get('legend').invoke('text').should('not.be.empty');
      });
    });

    // Verify all radio buttons and checkboxes in fieldset have labels
    cy.get('fieldset input[type="radio"], fieldset input[type="checkbox"]').each(($input) => {
      const inputId = $input.attr('id');
      if (inputId) {
        cy.get(`label[for="${inputId}"]`).should('exist');
      }
    });

    cy.checkA11y();
  });

  it('should verify form fields are keyboard accessible with labels', () => {
    // Test keyboard navigation through labeled fields
    cy.get('input[id], textarea[id], select[id]').first().focus();
    cy.focused().should('have.attr', 'id');

    // Tab through form fields
    cy.get('body').tab();
    cy.focused().should('have.attr', 'id');

    // Verify each focused field has an associated label
    cy.focused().then(($focused) => {
      const focusedId = $focused.attr('id');
      if (focusedId) {
        cy.get(`label[for="${focusedId}"]`).should('exist');
      }
    });

    cy.checkA11y();
  });
});
